mapper.select:
SELECT id,task_num,type,task_detail,task_address,site_route,principal,end_time,create_time,status,deal_method,evaluate, deal_result,move_stack_target_siteroute,move_stack_target_name,target_siteid FROM tb_task
AND task_num like concat(concat('%', #{taskDto.taskNum}), '%')
AND site_route like concat(concat('%',#{taskDto.siteRoute}),'%')
AND status = #{taskDto.status}
AND type = #{taskDto.type}
AND principal = #{taskDto.principal}
AND end_time <= TO_DATE(#{taskDto.endTime}, 'SYYYY-MM-DD HH24:MI:SS' )
AND end_time >= TO_DATE(#{taskDto.endStartTime}, 'SYYYY-MM-DD HH24:MI:SS' )
ORDER BY create_time DESC

SELECT id,task_num,type,task_detail,task_address,site_route,principal,end_time,create_time,status,deal_method,evaluate,deal_result, move_stack_target_siteroute,move_stack_target_name,target_siteid FROM tb_task
AND task_num like concat(concat('%', #{taskDto.taskNum}), '%')
AND site_route like concat(concat('%',#{taskDto.siteRoute}),'%')
AND status = #{taskDto.status}
AND type = #{taskDto.type}
AND principal = #{taskDto.principal}
AND end_time <= TO_DATE(#{taskDto.endTime}, 'SYYYY-MM-DD HH24:MI:SS' )
AND end_time >= TO_DATE(#{taskDto.endStartTime}, 'SYYYY-MM-DD HH24:MI:SS' )
ORDER BY create_time DESC

mapper.update:
UPDATE tb_task
deal_method = #{taskDto.dealMethod}, deal_result = #{taskDto.dealResult}, principal = #{taskDto.principal}, status = #{taskDto.status}, finish_time = sysdate
WHERE id = #{taskDto.id}

UPDATE tb_task
evaluate = #{taskDto.evaluate}, evaluate_user = #{taskDto.evaluateUser}, evaluate_time = TO_DATE(#{taskDto.evaluateTime}, 'SYYYY-MM-DD HH24:MI:SS' )
WHERE id = #{taskDto.id}

