SELECT count(1) as "sum",to_char( create_time, 'YYYY-MM-DD') AS "day"
FROM tb_task
WHERE to_char( create_time, 'YYYY-MM-DD') in

    #{day}


    AND type = #{taskDto.type}


    AND site_route like concat(concat('%', #{taskDto.taskSiteRoute}), '%')


    AND principal = #{taskDto.principal}

GROUP BY to_char( create_time, 'YYYY-MM-DD')
ORDER BY "day"

